type AssetPack = Partial<Record<RacerName, string>>;
type AssetMode = 'original' | 'imported';
type SoundName = 'roll' | 'move' | 'move-back' | 'event' | 'finish' | 'click';
type PendingAbility = { action: AbilityActionId; targetId?: string };
type DiceRoll = { racerId: string; from: number; to: number; value: number | null; phase: 'rolling' | 'result'; path?: number[] };
type DraftState = { pick: number; startPlayer: number; pool: RacerName[] };
type AbilityActivation = { racer: RacerState; ownerName: string; label: string };
type MagicianPrompt = { baseState: GameState; candidateState: GameState; racerId: string; from: number; to: number; value: number; rerollsLeft: number };
type FinishCelebration = { place: 1 | 2; racer: RacerState };
type IconName = 'arrow-right' | 'arrow-up-right' | 'book' | 'check' | 'close' | 'dice' | 'download' | 'flag' | 'globe' | 'headphones' | 'lightning' | 'logout' | 'moon' | 'music' | 'play' | 'sparkles' | 'star' | 'trophy' | 'users' | 'volume-off' | 'volume-on' | 'wand' | 'wifi';
const assetStorageKey = 'magical-athlete-asset-pack-v1';
const gameStorageKey = 'hu-nao-yun-dong-hui-game-v1';
const assetSlug = (value: string) => value.toLowerCase().replace(/\.[^.]+$/, '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const cardSlug = (name: RacerName) => assetSlug(name);
const bytesToDataUrl = (data: Uint8Array, mime: string) => { let binary = ''; for (let index = 0; index < data.length; index += 0x8000) binary += String.fromCharCode(...data.subarray(index, index + 0x8000)); return `data:${mime};base64,${btoa(binary)}`; };
const loadStoredAssetPack = (): AssetPack => { if (typeof window === 'undefined') return {}; try { const stored = window.localStorage.getItem(assetStorageKey); return stored ? JSON.parse(stored) as AssetPack : {}; } catch { return {}; } };
const snakeOrder = (playerCount: number, startPlayer: number) => { const forward = Array.from({ length: playerCount }, (_, index) => (startPlayer + index) % playerCount); return [...forward, ...[...forward].reverse()]; };
const draftOrder = (playerCount: number, startPlayer: number) => [...snakeOrder(playerCount, startPlayer), ...snakeOrder(playerCount, (startPlayer + 1) % playerCount)];
const shuffleNames = (names: RacerName[]) => [...names].sort(() => Math.random() - 0.5);
const drawDraftPool = (playerCount: number, used: RacerName[] = []) => { const usedSet = new Set(used); return shuffleNames(RACERS.filter((racer) => !usedSet.has(racer.name)).map((racer) => racer.name)).slice(0, playerCount * 2); };
const cloneGameState = (state: GameState) => structuredClone(state);
const drawStartingPlayer = (playerCount: number) => Math.floor(Math.random() * playerCount);

function useSounds(enabled: boolean, scene: AudioScene, settings: AudioSettings) {
  const directorRef = useRef<AudioDirector | null>(null);
  useEffect(() => {
    const director = new AudioDirector(settings); directorRef.current = director;
    const unlock = () => { void director.unlock(); };
    const visibility = () => document.hidden ? director.suspend() : director.resume();
    window.addEventListener('pointerdown', unlock, { once: true }); window.addEventListener('keydown', unlock, { once: true }); document.addEventListener('visibilitychange', visibility);
    return () => { window.removeEventListener('pointerdown', unlock); window.removeEventListener('keydown', unlock); document.removeEventListener('visibilitychange', visibility); director.destroy(); directorRef.current = null; };
  // The director owns its context for the lifetime of this page.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  useEffect(() => { directorRef.current?.setSettings({ ...settings, muted: !enabled || settings.muted }); }, [enabled, settings]);
  useEffect(() => { directorRef.current?.setScene(scene); }, [scene]);
  return useCallback((name: SoundName) => {
    const director = directorRef.current; if (!director || !enabled) return; void director.unlock();
    const cue = name === 'roll' ? 'dice-shake' : name === 'move' ? 'step-forward' : name === 'move-back' ? 'step-back' : name === 'event' ? 'ability' : name === 'finish' ? 'first' : 'button';
    director.play(cue); if (name === 'event') director.duck(-8, 700); if (name === 'finish') director.duck(-12, 1800);
  }, [enabled]);
}

